  "tour.s6.satz":"If something is off, this button writes a report \u2013 without your combat log. Attach it to an issue.",
  "tour.wo.start":"Found on Start.", "tour.wo.titel":"Found at the top, in the title bar.",
  "tour.wo.leiste":"Found on the left, in the side bar.", "tour.wo.status":"Found at the bottom, in the status bar.",
  "einst.thema":"Theme", "einst.themaAuto":"Auto",
  "einst.glasSatz":"Smoked glass lets what lies behind the window show through, blurred (Windows 11). Elsewhere it stands on solid smoke grey.",
  "einst.glasOhne.browser":"Solid smoke grey here: in the browser there is no Windows background.",
  "einst.glasOhne.system":"Solid smoke grey here: the blurred background needs Windows 11 (2022 update or later).",
  "einst.glasOhne.aus":"Solid smoke grey here: transparency effects are off in Windows.",
  "einst.groesse":"Interface size",
  "einst.groesseSatz":"Everything in Borometer bigger or smaller, 10 to 200\u00a0%. Ctrl and plus or minus does the same, Ctrl+0 goes back to 100\u00a0%.",
  "einst.sprache":"Interface language", "einst.spracheSatz":"Every sentence exists in both languages.",
  "einst.seeSatz":"How much of the game shows through the compact window, 0 to 55\u00a0%.",
  "einst.an":"On", "einst.aus":"Off", "einst.kuerzel":"Click-through",
  "einst.fenstBrowser":"This section concerns the app\u2019s window. In the browser, the browser draws the window.",
  "einst.ordner":"Combat log folder",
  "einst.ordnerSatz":"Borometer reads the game\u2019s combat logs from this folder, and only reads them.",
  "einst.ordnerBrowser":"In the browser there is no folder to watch: the browser opens single files. Drag a log onto the window or pick one on the start page.",
  "einst.ordnerKeiner":"No folder found yet", "einst.aendern":"Change folder", "einst.ordnerAendern":"Change combat log folder",
  "einst.explorer":"Show in Explorer", "einst.ordnerExplorer":"Show combat log folder in Explorer",
  "einst.explorerNicht":"The log folder cannot be opened right now. Is it still there? If not, \u201cChange folder\u201d helps.",
  "einst.phasenSatz":"Some bosses go untargetable for a phase. On, Borometer connects those phases into one fight; off, it splits at every pause.",
  "einst.kampfdatei":"Fight file", "einst.kampfdateiSatz":"Every saved fight in one file, to keep or to open on another computer.",
  "einst.speichern":"Save", "einst.laden":"Load",
  "einst.devSatz":"Shows the log setup, the CSV export, \u201cBy weapon\u201d and the example party \u2013 tools for checking a log.",
  "einst.beispielSatz":"Up to three example members made from the fights in the log, to try the group views. A second click clears them.",
  "einst.beispielKnopf":"Show or clear",
  "einst.sichLiest":"Reads", "einst.sichLiestSatz":"The combat log folder, read only, and Borometer\u2019s own files.",
  "einst.sichSchreibt":"Writes", "einst.sichSchreibtSatz":"Only into its own folders <code>Logs</code>, <code>Party-Logs</code> and <code>Bug-Reports</code>, into its settings and, while the archive is on, into the folder <code>archiv</code> beside them.",
  "einst.sichServer":"Local server", "einst.sichServerSatz":"Listens only on <code>127.0.0.1</code>. Only while you host a party is the party access reachable from outside.",
  "einst.sichSpiel":"Game", "einst.sichSpielSatz":"No access: nothing hooks into the game, nothing reads its memory.",
  "einst.sichNetz":"Network", "einst.sichNetzSatz":"Only when you use a party or turn on the update notice.",
  "einst.updatePruefen":"Check for a new version at start", "einst.updatePruefenSatz":"Asks GitHub once per start which version is the newest. GitHub sees your IP address and the time. Nothing is downloaded or installed.",
  "einst.updateDa":"Version {v} is out \u2013 open the release page \u203a", "einst.updateTitel":"Opens the release page on GitHub in your browser",
  "einst.win":"Windows",
  "einst.winMelden":"Notify after every fight", "einst.winMeldenSatz":"Windows shows the result when a fight is over and Borometer is not in front.",
  "einst.winNurBest":"Only for a new best", "einst.winNurBestSatz":"Stays quiet unless the fight beats your best pull.",
  "einst.winTray":"Close to the notification area", "einst.winTraySatz":"Closing hides the window; live logging goes on. Quit from the icon’s menu.",
  "einst.winAuto":"Start with Windows", "einst.winAutoSatz":"Opens minimized when you sign in, or only in the notification area when “Close to the notification area” is on.",
  "einst.fehler":"Bug report",
  "einst.fehlerSatz":"Now at the bottom right of the status bar: \u201cReport a bug\u201d. It saves a JSON file that describes what Borometer saw \u2013 without the combat log itself. Attach it to an issue, ideally with the combat log.",
  "einst.beispielkampf":"Sample fight", "einst.beispielkampfSatz":"Two fights to try Borometer without a log of your own. They replace what is loaded now.",
  // Kampfwahl (Instrumententafel 3.2)
