  "weapons.skillsTitle":"Skills in this fight",
  /* Hier stand, eine Faehigkeit, die man nicht anfasst, bleibe ohne Waffe
     und werde aus der Aufteilung herausgelassen. Beide Haelften stimmten
     nicht, und der Kommentar in renderWeapons sagt es seit jeher richtig:
     "Ohne Waffe heisst: weder von Hand gesetzt noch aus der Tabelle bekannt."
     weaponFor() nimmt deine Wahl, dann autoWeapon(), dann erst "Unassigned".
     autoWeapon() schlaegt die ID in SKILL_WEAPON nach und den Namen in
     NAME_TO_WEAPON, das aus derselben Tabelle gebaut wird; die Datei misst
     die Deckung an anderer Stelle selbst mit 99,987 Prozent des Schadens
     ueber 92 Logs. Der Satz beschrieb also die Ausnahme als Regel.
     Und herausgelassen wird nichts: byWeapon() filtert nicht, "Unassigned"
     wird eine gewoehnliche Zeile in der Waffentabelle darueber. */
  "weapons.skillsDesc":"A skill you leave alone gets the weapon that Borometer's built-in skill table holds for its id or its name. Only a skill the table cannot place is left without a weapon, and it gets its own row in the table above.",
