  "hinweis.region":"Hinweis zum Bereich", "hinweis.verstanden":"Verstanden",
  "hinweis.timeline":"Der Ring um deine DPS, rechts die Treffer. Strg+Pfeil links oder rechts wechselt den Kampf.",
  "hinweis.rotation":"Wann du was gewirkt hast, auf einer Zeitleiste. Die Leertaste spielt sie ab, die Pfeiltasten gehen Schritt für Schritt.",
  "hinweis.analysis":"Ordnet den Kampf nach Fähigkeiten und sagt, wo Schaden liegen blieb.",
  "hinweis.compare":"Zwei Kämpfe, Fähigkeit gegen Fähigkeit.",
  "hinweis.history":"Jeder Kampf, den Borometer gesehen hat, je Boss.",
  "hinweis.party":"Ein Board für alle, die mit dem Code beitreten.",
  "hinweis.weeklies":"Deine Wochenaufgaben je Charakter. Mit den Pfeiltasten gehst du durch die Kacheln.",
  "hinweis.gilde":"Die Liste deiner Gilde mit Punkten. Mit / suchst du, N legt ein Mitglied an.",
  "hinweis.rekorde":"Deine besten Pulls je Boss.",
  "hinweis.archiv":"Deine Bosskämpfe als Kopie, je Boss. Sie bleiben, auch wenn du die Kampflogs löschst.",
  "hinweis.settings":"Thema, Größe, Sprache und Schalter. Diese Hinweise schaltest du hier auch aus.",
  "einst.bereichHinweise":"Hinweise zu den Bereichen",
  "einst.bereichHinweiseSatz":"Beim ersten Besuch eines Bereichs steht eine Zeile da, was er tut. Gemerkt wird nur, welche du gesehen hast.",
  "tour.schritt":"Schritt {n} von {total}", "tour.weiter":"Weiter", "tour.zurueck":"Zurück", "tour.fertig":"Fertig", "tour.skip":"Überspringen",
  "tour.ordnerGesetzt":"Ordner gesetzt",
  "tour.s1.titel":"Log-Ordner",
  "tour.s1.satz":"Borometer liest nur die Kampf-Logs, die Throne and Liberty selbst schreibt. Wähle dafür den Ordner <code>CombatLogs</code>.",
  "tour.s1.satzDatei":"Borometer liest nur die Kampf-Logs, die Throne and Liberty selbst schreibt. Öffne dafür eine Logdatei aus dem Ordner <code>CombatLogs</code>.",
  "tour.s2.titel":"Live",
  "tour.s2.satz":"Ein Klick, und Borometer liest jeden neuen Kampf, sobald das Spiel ihn schreibt \u2013 also beim Kampfende. Ein zweiter Klick hört auf.",
  "tour.s3.titel":"Kampfwahl",
  "tour.s3.satz":"Hier wählst du den Kampf, auch von früheren Tagen. Strg+K öffnet sie von überall.",
  "tour.s4.titel":"Kompakt",
  "tour.s4.satz":"Ein schmaler Streifen über dem Spiel.",
  "tour.s4.kuerzel":"{key} macht ihn durchklickbar, damit deine Klicks ins Spiel gehen.",
  "tour.s4.kuerzelRueckfall":"{key} schaltet das Durchklicken.",
  "tour.s5.titel":"Weeklies",
  "tour.s5.satz":"Deine Wochenaufgaben je Charakter, mit dem Reset am Donnerstag um 10:00.",
  "tour.s6.titel":"Fehler melden",
  "tour.s6.satz":"Stimmt etwas nicht, legt dieser Knopf einen Bericht an \u2013 ohne dein Kampflog. Hänge ihn an ein Issue.",
