  "einst.thema":"Thema", "einst.themaAuto":"Auto",
  "einst.glasSatz":"Rauchglas lässt verwischt durchscheinen, was hinter dem Fenster liegt (Windows 11). Sonst steht es auf festem Rauchgrau.",
  "einst.glasOhne.browser":"Hier auf festem Rauchgrau: im Browser gibt es keinen Windows-Hintergrund.",
  "einst.glasOhne.system":"Hier auf festem Rauchgrau: der verwischte Hintergrund braucht Windows 11 (ab dem Update 2022).",
  "einst.glasOhne.aus":"Hier auf festem Rauchgrau: die Transparenzeffekte sind in Windows aus.",
  "einst.groesse":"Gr\u00f6\u00dfe der Oberfl\u00e4che",
  "einst.groesseSatz":"Alles in Borometer gr\u00f6\u00dfer oder kleiner, 10 bis 200\u00a0%. Strg und Plus oder Minus tut dasselbe, Strg+0 geht zur\u00fcck auf 100\u00a0%.",
  "einst.sprache":"Sprache der Oberfl\u00e4che", "einst.spracheSatz":"Jeder Satz steht in beiden Sprachen.",
  "einst.seeSatz":"Wie viel vom Spiel durch das Kompaktfenster scheint, 0 bis 55\u00a0%.",
  "einst.an":"An", "einst.aus":"Aus", "einst.kuerzel":"Durchklickbar",
  "einst.fenstBrowser":"Dieser Abschnitt betrifft das Fenster der App. Im Browser zeichnet der Browser das Fenster.",
  "einst.ordner":"Kampflog-Ordner",
  "einst.ordnerSatz":"Aus diesem Ordner liest Borometer die Kampf-Logs des Spiels, und liest sie nur.",
  "einst.ordnerBrowser":"Im Browser gibt es keinen Ordner zum Beobachten: der Browser \u00f6ffnet einzelne Dateien. Zieh ein Log auf das Fenster oder w\u00e4hle es auf der Startseite.",
  "einst.ordnerKeiner":"Noch kein Ordner gefunden", "einst.aendern":"Ordner \u00e4ndern", "einst.ordnerAendern":"Kampflog-Ordner \u00e4ndern",
  "einst.explorer":"Im Explorer zeigen", "einst.ordnerExplorer":"Kampflog-Ordner im Explorer zeigen",
  "einst.explorerNicht":"Der Log-Ordner l\u00e4sst sich gerade nicht \u00f6ffnen. Ist er noch da? Sonst hilft \u201eOrdner \u00e4ndern\u201c.",
  "einst.phasenSatz":"Manche Bosse sind zwischendurch nicht anvisierbar. Eingeschaltet verbindet Borometer diese Phasen zu einem Kampf, ausgeschaltet trennt es an jeder Pause.",
  "einst.kampfdatei":"Kampfdatei", "einst.kampfdateiSatz":"Alle gespeicherten K\u00e4mpfe in einer Datei, zum Aufheben oder f\u00fcr einen anderen Rechner.",
  "einst.speichern":"Speichern", "einst.laden":"Laden",
  "einst.devSatz":"Zeigt die Log-Einrichtung, den CSV-Export, \u201eNach Waffe\u201c und die Beispielgruppe \u2013 Werkzeuge, um ein Log zu pr\u00fcfen.",
  "einst.beispielSatz":"Bis zu drei Beispielmitglieder aus den K\u00e4mpfen im Log, um die Gruppenansichten auszuprobieren. Ein zweiter Klick r\u00e4umt sie weg.",
  "einst.beispielKnopf":"Zeigen oder wegr\u00e4umen",
  "einst.sichLiest":"Liest", "einst.sichLiestSatz":"Den Kampflog-Ordner, nur lesend, und die eigenen Dateien von Borometer.",
  "einst.sichSchreibt":"Schreibt", "einst.sichSchreibtSatz":"Nur in die eigenen Ordner <code>Logs</code>, <code>Party-Logs</code> und <code>Bug-Reports</code>, in seine Einstellungen und, solange das Archiv an ist, in den Ordner <code>archiv</code> daneben.",
  "einst.sichServer":"Lokaler Server", "einst.sichServerSatz":"H\u00f6rt nur auf <code>127.0.0.1</code>. Nur wenn du eine Gruppe hostest, ist der Gruppenzugang von au\u00dfen erreichbar.",
  "einst.sichSpiel":"Spiel", "einst.sichSpielSatz":"Kein Zugriff: kein Eingriff ins Spiel, kein Lesen seines Speichers.",
  "einst.sichNetz":"Netz", "einst.sichNetzSatz":"Nur wenn du eine Gruppe nutzt oder den Update-Hinweis einschaltest.",
  "einst.updatePruefen":"Beim Start nach neuer Version sehen", "einst.updatePruefenSatz":"Fragt einmal je Start bei GitHub, welche Version die neueste ist. GitHub sieht dabei deine IP-Adresse und die Uhrzeit. Geladen oder installiert wird nichts.",
  "einst.updateDa":"Version {v} ist da \u2013 Release-Seite \u00f6ffnen \u203a", "einst.updateTitel":"\u00d6ffnet die Release-Seite bei GitHub im Browser",
  "einst.win":"Windows",
  "einst.winMelden":"Nach jedem Kampf melden", "einst.winMeldenSatz":"Windows zeigt das Ergebnis, wenn ein Kampf vorbei ist und Borometer nicht vorn ist.",
  "einst.winNurBest":"Nur bei neuem Bestwert", "einst.winNurBestSatz":"Bleibt still, außer der Kampf schlägt deinen besten Pull.",
  "einst.winTray":"Beim Schließen in den Infobereich", "einst.winTraySatz":"Schließen verbirgt das Fenster, die Live-Aufzeichnung läuft weiter. Beenden über das Menü des Symbols.",
  "einst.winAuto":"Mit Windows starten", "einst.winAutoSatz":"Öffnet minimiert, wenn du dich anmeldest, oder nur im Infobereich, wenn „Beim Schließen in den Infobereich“ an ist.",
  "einst.fehler":"Fehlerbericht",
  "einst.fehlerSatz":"Steht jetzt als \u201eFehler melden\u201c unten rechts in der Statusleiste. Er speichert eine JSON-Datei, die beschreibt, was Borometer gesehen hat \u2013 ohne das Kampflog selbst. H\u00e4ng sie an ein Issue, am besten mit dem Kampflog dazu.",
  "einst.beispielkampf":"Beispielkampf", "einst.beispielkampfSatz":"Zwei K\u00e4mpfe, um Borometer ohne eigenes Log auszuprobieren. Sie ersetzen, was gerade geladen ist.",
